INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(3800, 0, 38, 0, 0, 0, 'Loch Modan', 'Loch Modan is a highland of green hills and pine woods east of Dun Morogh, held by the dwarves of Ironforge and named for the great lake at its heart. At the loch''s northern end the Stonewrought Dam holds back its waters, one of the grandest works ever raised. In the Second War the orcs of the Horde overran these hills, and the dwarves won them back once the war was done. Today the region is thinly guarded. Many of Ironforge''s soldiers have marched off to distant fronts, leaving a handful of mountaineers in the guard towers and the town of Thelsamar to hold the line. They have plenty to hold it against: Stonesplinter troggs boiling up out of the earth, Tunnel Rat kobolds in the western hills, Mo''grosh ogres in the northeast, Dragonmaw orcs pressing into the pass of Dun Algaz, and Dark Iron saboteurs creeping toward the dam itself.', 'warcraft.wiki.gg/wiki/Loch_Modan (loch gave the region its name; Horde overran it in the Second War, dwarves reclaimed it); quest 1558 description (dam one of the biggest things anyone has made); quests 224, 237, 267 (reserves called to the front, troggs tunneling up); quest 255 (few soldiers spared); quest 416 (tunnel rat kobolds west of Thelsamar); quest 256 (ogres in the northeast); quest 455 (Dragonmaw in Dun Algaz); quest 250 (Dark Iron threat to the dam)'),
(3801, 1, 38, 1, 0, 0, 'Valley of Kings', 'In the southwestern corner of Loch Modan, where the road from Dun Morogh comes through the mountains, two colossal stone dwarves stand watch over the pass into the southlands. They depict King Madoran Bronzebeard and King Khardros Wildhammer, raised in their honor by their sons after both kings had died, as a warning to any who would attack the dwarven realms and a reminder of the price the Dark Irons paid for their treachery. Nearby stands the southern guard tower, where Captain Rugelfuss and his regiment guard the gate and wage war on the troggs in the hills. Farther south, a locked gate leads to the Searing Gorge, and Mountaineer Pebblebitty refuses entry to nearly everyone who asks.', 'page_text 1929-1930, in-game book War of the Three Hammers (gameobject 175739): the sons of Madoran and Khardros commissioned the statues, which guard the pass into the southlands as a warning and a reminder of the Dark Irons'' price; warcraft.wiki.gg/wiki/Valley_of_Kings (statues of Madoran and Khardros commissioned by their sons, guard the pass into the southlands; cites History of Warcraft); quest 267 description (regiment watches over the Gate); quest 224 log (southern guard tower); quests 3182, 3201 (key to the Searing Gorge); npc_text for Mountaineer Pebblebitty 3836 (gossip menu 50000); DB spawns: Rugelfuss 1092, Cobbleflint 1089, Pebblebitty 3836 in area 924 (Pebblebitty south of the tower)'),
(3802, 1, 38, 2, 0, 0, 'Stonesplinter Valley', 'In the mountains of southwestern Loch Modan lies Stonesplinter Valley, the heartland of the Stonesplinter troggs. These brutish creatures were unearthed from caverns far below by the dwarves'' own digging, and they have been tunneling up from every crevice ever since. Scouts and seers, skullthumpers, bonesnappers and shamans swarm across the slopes, and deep within the valley their chieftain Grawmug keeps his lair behind his two hulking guards, Gnasher and Brawler. The troggs make no secret of their ambitions. Their battle cries proclaim that the Loch now belongs to the Stonesplinter tribe.', 'warcraft.wiki.gg/wiki/Stonesplinter_Valley (southwestern Loch Modan, Grawmug deep in the valley); warcraft.wiki.gg/wiki/Loch_Modan (troggs unearthed from caves below by the dwarven digs); quest 224 description (tunneling up from every crevice); quest 217 description; creature_text 1205 (the Loch belongs to the Stonesplinter Tribe); DB spawns in area 923: Stonesplinter Trogg, Scout, Seer, Skullthumper, Shaman, Bonesnapper; Grawmug 1205, Gnasher 1206, Brawler 1207'),
(3803, 1, 38, 3, 0, 0, 'Grizzlepaw Ridge', 'Grizzlepaw Ridge is a wooded height rising south of Thelsamar, with Stonesplinter Valley spread out to the west. It is bear country. Grizzled black bears and great patriarchs roam its slopes, and somewhere in the hills above Thelsamar lies the lair of Ol'' Sooty, a large bear the hunters of the Farstrider Lodge tried and failed to bring down. One of those who tried was young Daryl, who came back with nothing to show for it but a scar over his eye. Now and then the old bear comes down from its den to maul anyone foolish enough to provoke it.', 'warcraft.wiki.gg/wiki/Grizzlepaw_Ridge (south of Thelsamar, east of Stonesplinter Valley, bears, Ol'' Sooty comes down to attack those who provoke him); quest 271 description; DB spawns in area 936: Grizzled Black Bear, Black Bear Patriarch, Ol'' Sooty 1225'),
(3804, 1, 38, 4, 0, 0, 'Thelsamar', 'Thelsamar is the chief town of Loch Modan, a cluster of stout dwarven houses on the western side of the loch, just off the road that runs between Dun Morogh and the Wetlands. Magistrate Bluntnose governs it, the Thelsamar Mountaineers patrol its lanes, and the Explorers'' League keeps a branch house here, where Jern Hornhelm serves as contact for the digs. The Stoutlager Inn promises full tankards and long stories, and the town is famous for its blood sausages, with hungry workers from the excavation crowding in after a hard day''s work. Thorgrum Borrelson keeps the gryphon roost and swears no faster gryphons fly anywhere in the Eastern Kingdoms.', 'warcraft.wiki.gg/wiki/Thelsamar (west side of Loch Modan, road toward Dun Morogh and the Wetlands, Stoutlager Inn, Thelsamar Mountaineers); npc_text for Mountaineer Kadrell 1340 (Thelsamar branch of the Explorers'' League); quest 298 (Jern Hornhelm, local contact); npc_text for Innkeeper Hearthstove 6734; quest 418 description (famous for blood sausages, excavation workers); npc_text for Thorgrum Borrelson 1572; AreaTable: 2101 Stoutlager Inn, parent 38'),
(3805, 1, 38, 5, 0, 0, 'Silver Stream Mine', 'North of Thelsamar, the Silver Stream Mine was once a rich source of silver for the dwarves of Ironforge. When its veins ran dry, the Miners'' League turned the old tunnels into a storage depot, stacking crates of tools and gear in its galleries. Now Tunnel Rat kobolds have moved in and are pawing through good dwarven tools, and the mountaineers are itching for the order to clear them out. The League would rather its gear were carried out first, before the soldiers start breaking things. Among the vermin skulks a rarely seen kobold called Grizlak.', 'quest 307 description and reward text; warcraft.wiki.gg/wiki/Silver_Stream_Mine (bountiful source of silver, storage depot); DB spawns in area 149: Tunnel Rat kobolds, Miners League Crates (gameobject 271), Grizlak 1425 (rank 4)'),
(3806, 1, 38, 6, 0, 0, 'Algaz Station', 'Just east of the North Gate Pass from Dun Morogh stands Algaz Station, the northern guard tower of Loch Modan, a dwarven outpost manned by mountaineers and named for the pass of Dun Algaz beyond it. From the top of the tower Mountaineer Gringer Stormpike keeps watch, a member of a proud and wealthy clan with discerning tastes: he has commissioned an axe from a smith in Stormwind and ordered a shield from Furen Longbeard, a dwarven armorsmith he admires in that city''s dwarven district. The armorer Gothor Brumn serves those passing through, and the kobold-infested Silver Stream Mine lies a short way to the east.', 'warcraft.wiki.gg/wiki/Algaz_Station (east of North Gate Pass, south of Dun Algaz, takes its name from it, mountaineers, Stormpike, Gothor Brumn); quest 353 (Gringer Stormpike, northern guard tower, axe from Grimand Elmore); quest 1338 and reward text (Furen Longbeard, proud and rich clan); quest 1339 (top of the northern guard tower); quest 307 (mine to the east); DB spawns: Stormpike 1343, Gothor Brumn 1362 in area 925'),
(3807, 1, 38, 7, 0, 0, 'Dun Algaz', 'Dun Algaz is the mountain pass that carries the road north out of Loch Modan into the Wetlands and on to Menethil Harbor, the Alliance port and stronghold on the coast. Its stronghold has a long and bloody past. When the Horde was driven south across the Thandol Valley in the Second War, Dun Algaz became its last hold, and the assault Anduin Lothar ordered against it failed. Now the orcs have returned. Dragonmaw warriors from the Wetlands have pushed into the pass, threatening to cut Loch Modan off from Menethil, and Mountaineer Rockgar is calling for volunteers to break through.', 'warcraft.wiki.gg/wiki/Dun_Algaz (Second War: orcs retreated south across the Thandol Valley, Lothar''s assault failed, last hold; original WoW: Dragonmaw overran the post); quest 455 description and reward text; quest 468 description; DB spawn: Mountaineer Rockgar 1342 in area 837'),
(3808, 1, 38, 8, 0, 0, 'Stonewrought Dam', 'The Stonewrought Dam spans the northern end of the loch, a vast wall of stone holding back its waters, which spill down a great waterfall toward the Wetlands below. It is counted among the greatest works the dwarves ever built, and even an orphan of Stormwind begs to be taken to see it. Far beneath it, at the very foot of the falls, grows the musquash root, found nowhere else. Today it is the Dark Iron clan that threatens the dam, with sappers lurking on its eastern ramp and insurgents swimming at its base. Chief Engineer Hinderweir VII oversees the dam with a small company of mountaineers, much of its security detail having been called away to the front.', 'quest 1558 description and reward text (Children''s Week: huge dam, big waterfall, rushing water); quest 335 description (Musquash Root found only at the base of the falls far beneath the dam); quests 250, 280 descriptions (sappers on the eastern ramp, insurgents swimming a keg to the base, security detail reassigned); DB spawns in area 146: Hinderweir 1093, Mountaineers Haggis, Angst, Haggil, Morlic, Barn, Dark Iron Sapper 1222, Dark Iron Insurgent 1169; warcraft.wiki.gg/wiki/Stonewrought_Dam (checked: Franclorn claim rests on the Cataclysm archaeology Pipe item and the non-canon RPG, not used)'),
(3809, 1, 38, 9, 0, 0, 'The Loch', 'The loch that gives the land its name is the largest body of water in all of Khaz Modan, its waters held high by the Stonewrought Dam. Islands rise from its cold waters and the crocolisks have claimed them, making the loch famous among hunters who come for skins and meat. Threshadons glide through its depths. Fishermen ply their trade along the western shore northeast of Thelsamar, and the road to the excavation runs south from town along the curve of the shore, where porters hauling blastpowder were recently ambushed by Dark Irons. Troggs have crept onto one of the islands too, and a crashed gnomish pilot waits nearby for his stolen tools.', 'warcraft.wiki.gg/wiki/The_Loch (largest body of water in Khaz Modan, threshadons); warcraft.wiki.gg/wiki/Stonewrought_Dam (more than doubling its size); quest 385 description (famous crocs entrenched on the islands); quest 273 description and reward text (route following the curve of the Loch, Dark Iron ambush); quest 2038 description (crash, troggs from the nearby island); DB spawns in area 556: Young Threshadon, Loch Crocolisk, Warg Deepwater (fishing trainer) and Khara Deepwater (fishing supplies) at 40,39, Huldar and Miran at 52,69, Bingles 6577'),
(3810, 1, 38, 10, 0, 0, 'Mo''grosh Stronghold', 'In the caves and hills of northeastern Loch Modan, across the water from Thelsamar, the Mo''grosh ogres have made their stronghold. Brutes, enforcers, shamans and mystics crowd the camp, and from here they raid the whole region: Thelsamar, the dam and the excavation site have all suffered, and an ore caravan bound from the Wetlands was ambushed and its cargo carried off. The ogres also mine rare crystals, and a crushed one is needed for the mixture that renders seaforium powder harmless. The magistrate of Thelsamar has put a price on their leader, Chok''sul, and a brute called Emogg the Crusher is sometimes seen among them.', 'warcraft.wiki.gg/wiki/Mo''grosh_Stronghold (ogre-infested caves in northeastern Loch Modan; only this part used); quest 256 description; quest 255; quest 1655 description (northeast across the Loch, caravan from the Wetlands ambushed); quests 274, 278 (Mo''grosh crystal, ogres to the northeast mine them, rare); DB spawns in area 143: Mo''grosh Ogre, Enforcer, Brute, Shaman, Mystic, Emogg the Crusher 14267, Bailor''s Ore 92420'),
(3811, 1, 38, 11, 0, 0, 'The Farstrider Lodge', 'In southeastern Loch Modan stands the Farstrider Lodge, a hunting lodge built in the high elven style, though only one elf still lives there. Its other residents are dwarven and human hunters, and Marek Ironheart, who leads them, prizes hunting skill above all else. Trainers, a bowyer and a gunsmith keep busy here, and hunters come from afar for the loch''s famous crocolisks, whose skins and meat always find buyers. Buzzards nest in the hills nearby and great boars roam the meadows, giving the lodge''s resident braggart, young Daryl the Youngling, endless excuses to challenge newcomers.', 'warcraft.wiki.gg/wiki/Farstrider_Lodge (high elven make, only one high elf, humans and dwarves, Marek Ironheart leader); npc_text for Marek Ironheart 1154; quest 385 description; quests 257, 258; DB spawns in area 147: Dargh Trueaim, Claude Erksine, Cliff Hadin, Irene Sureshot, Daryl 1187, Vyrin 1156, Marek 1154'),
(3812, 1, 38, 12, 0, 0, 'Ironband''s Excavation Site', 'East of the loch, beyond its southern tip, Prospector Ironband of the Explorers'' League leads a dig into ancient ruins. Not long before trouble struck, his crews uncovered a large number of strange carved idols. Soon afterward Stonesplinter troggs surfaced within the site itself, drove the dwarves out of the ruins and took the idols, which seem to send the creatures berserk. Trogg diggers and geomancers now overrun the pits under Boss Galgosh, the Stonesplinter chieftain, and his tribal shaman Magosh. Ironband''s camp clings to the edge of the site, waiting on blastpowder from Thelsamar and on anyone willing to fight.', 'quest 436 description (ruins east of the lake, around the southern tip); quest 297 description; warcraft.wiki.gg/wiki/Ironband''s_Excavation_Site (southeastern Loch Modan, troggs of a large and volatile breed drove prospectors out); quests 298, 302, 309 (blastpowder); creature_template subnames 1398 Stonesplinter Chieftain, 1399 Stonesplinter Tribal Shaman; DB spawns in area 142: Stonesplinter Digger, Geomancer, Berserk Trogg, Ironband 1344, Fellhew 1345'),
(3813, 2, 38, 1, 1, 0, 'Chief Engineer Hinderweir VII', 'Chief Engineer Hinderweir VII is the dwarf charged with the care of the Stonewrought Dam, and he takes that charge very seriously. The Dark Iron clan has already destroyed the Thandol Span and pillaged Dun Modr, and Hinderweir is certain the dam is next. Yet most of his security detail, his best inspector included, has been reassigned to the front, leaving him to watch for saboteurs with whatever help he can find. When a suspicious barrel turns up near the eastern ramp he sends a sample to the explosives expert at Dun Modr, and he mixes the remedy himself once the ingredients are gathered.', 'quest 250 description; quests 161, 274, 278, 280, 283; npc_text for 1093 (dam saved); warcraft.wiki.gg/wiki/Chief_Engineer_Hinderweir_VII (pre-Cataclysm part only)'),
(3814, 2, 38, 2, 1, 0, 'Magistrate Bluntnose', 'Magistrate Bluntnose governs Thelsamar, and his patience with Ironforge is wearing thin. It took two months for word to come that a handful of soldiers might be spared for the town''s defense, and he was told it would take two more for them to arrive. Meanwhile Thelsamar, the excavation and above all the dam lie open to attack. Bluntnose has done the practical thing and hired mercenaries, sending them against the ogre camp, and he has posted a bounty on the ogre leader Chok''sul. Once the ogres are dealt with, he means to turn the town''s attention to the troggs.', 'quest 255 description and reward text; quest 256 (by order of the Magistrate of Thelsamar); warcraft.wiki.gg/wiki/Magistrate_Bluntnose (Mayor of Thelsamar)'),
(3815, 2, 38, 3, 1, 0, 'Prospector Ironband', 'Prospector Ironband leads the Explorers'' League dig east of the loch, a stout, honest dwarf who values results. Results have been hard to come by. Troggs have overrun his ruins, his reports earn only curses from the hot-tempered Prospector Stormpike in Ironforge, and a load of blastpowder sent to him weeks ago never arrived. He is convinced that the carved idols found at his site are what drives the troggs berserk. When his colleague Agmond was killed by troggs at a dig in the Badlands, Ironband began to fear that ancient urns unearthed there had stirred them up in just the same way.', 'quest 436 description (stout, honest dwarf who values results); quests 298, 301 (Stormpike: curse that Ironband, where did the blastpowder go); quest 297; quests 738, 739, 704 (Agmond, troggs, urns); warcraft.wiki.gg/wiki/Prospector_Ironband'),
(3816, 2, 38, 4, 1, 0, 'Captain Rugelfuss', 'Captain Rugelfuss commands the southern guard tower of Loch Modan, where his regiment watches over the gate and dares not leave it for fear of invasion. With the Ironforge Reserve called away to the front, he has a fraction of the soldiers he needs for the trogg war on his doorstep, so he relies on volunteers to carry the fight into the hills through his mountaineers Cobbleflint, Gravelgaw and Wallbang. The reinforcements promised to the tower never came. Rugelfuss''s answer is to strike at the head of the invasion: he wants the trogg chieftain Grawmug and both his guards dead.', 'quest 267 description; quests 224, 237 (reward text: reinforcements never showed), 263; quest 217 description; warcraft.wiki.gg/wiki/Loch_Modan (Rugelfuss sends dwarves against the troggs)'),
(3817, 2, 38, 5, 1, 0, 'Daryl the Youngling', 'Daryl the Youngling, who much prefers to be called Daryl the Bold, is a young human hunter at the Farstrider Lodge with a great gift for boasting and very little for manners. He sets newcomers hunting challenges he is sure are beyond them, gets their names wrong, belittles every kill and is plainly astonished whenever they succeed. He is fond of the story of the scar over his eye. What he leaves out is how he earned it: hunting Ol'' Sooty, the great bear of the hills above Thelsamar, and failing. Shown the beast''s head at last, his bravado collapses entirely.', 'quests 257, 258 descriptions, request and reward texts; quest 271 description (Vyrin''s account of the scar); quest 531 description; warcraft.wiki.gg/wiki/Daryl_the_Youngling (human hunter)'),
(3818, 2, 38, 6, 1, 0, 'Vyrin Swiftwind', 'Vyrin Swiftwind is the only high elf left at the Farstrider Lodge, a building of her people''s make. She has little patience for Daryl''s endless bragging and has been itching for months to get back at the stuck-up boy. She knows the true story of his scar: Ol'' Sooty, a bear that every hunter at the lodge failed to kill, mauled him when he tried his own luck. So Vyrin quietly recruits a capable hunter to slay the beast and show its head to Daryl, then savors the result. Those who help her are always welcome at the lodge, with her assurance that he had it coming.', 'quest 271 description; quest 531 description and reward text (itching for months to get back at that snooty, stuck-up boy); npc_text for 1156 (gossip menu 2831); warcraft.wiki.gg/wiki/Vyrin_Swiftwind (high elf); warcraft.wiki.gg/wiki/Farstrider_Lodge (high elven make, only one high elf)'),
(3819, 2, 38, 7, 1, 0, 'Bingles Blastenheimer', 'Bingles Blastenheimer is a gnome pilot who was sent to fly reconnaissance over Gnomeregan, the gnomish capital lost to troggs and leper gnomes. When he failed to report back for more than a week, his comrade Gnoarn in Ironforge was sure he had blown himself up. In truth he had crashed his gyrocopter into the loch, and troggs from a nearby island promptly made off with his tools and his special Blastencapper explosives. Stranded where he came down, Bingles has lost none of his zeal. He is convinced the movement to retake Gnomeregan depends on a gnomish air assault, and that it needs him.', 'quest 2039 description and reward text; quest 2038 description and reward text; DB: Gnoarn 6569 starts 2039, spawned in Ironforge'),
(3820, 2, 38, 8, 0, 0, 'Chok''sul', 'Chok''sul is the ogre whom the people of Thelsamar hold responsible for the raids on their town, the Stonewrought Dam and Ironband''s excavation, presumed to be the leader who plans and coordinates the Mo''grosh attacks. By order of the magistrate a bounty has been posted on him, payable on proof of his death, and the wanted notice names him plainly. He keeps to the ogre camp in the northeast of Loch Modan, a brute who sizes up every intruder as a possible meal. Whoever brings back his head can expect a magistrate who is first appalled, then delighted.', 'quest 256 description and reward text; creature_text 1210; DB spawn: Chok''sul 1210 at map 79.6,14.7 (northeast)'),
(3821, 2, 38, 9, 0, 0, 'Grawmug', 'Grawmug is the chieftain of the Stonesplinter troggs, the leader that the scouts of the southern guard tower have found behind the trogg incursion into Loch Modan. He keeps to the depths of Stonesplinter Valley and never goes anywhere without his two elite guards, Gnasher and Brawler. Grawmug makes no secret of his ambitions. He greets intruders with promises to eat them for breakfast and proclaims that the Loch, and all the lands around it, now belong to the Stonesplinter tribe. Captain Rugelfuss believes that with Grawmug dead the troggs might at last be pushed back into the ground.', 'quest 217 description and reward text; creature_text 1205; warcraft.wiki.gg/wiki/Stonesplinter_Valley (trogg leader deep in the valley)'),
(3822, 3, 38, 1, 1, 0, 'A Dark Threat Looms', 'With the Thandol Span destroyed and Dun Modr pillaged, Chief Engineer Hinderweir is sure the Stonewrought Dam will be the next Dark Iron target, and he is right. Dark Iron sappers are spotted on the dam''s eastern ramp, and nearby sits a suspicious barrel full of a strange-smelling powder. A sample is carried through the Algaz Gate and across the Wetlands to Ashlan Stonesmirk at Dun Modr, an explosives expert whose ears still ring from his trade. He knows it at once: seaforium, harmless while dry, but once wet enough to blow Ironforge out of its mountain. He sends back a disarming colloid, to be mixed with lurker venom, a crocolisk tear and a crushed Mo''grosh crystal. Meanwhile Dark Iron insurgents have swum a keg of the stuff to the base of the dam. The mixture is stirred in just in time, and the dam is saved, for the moment.', 'quests 250, 199, 161, 274, 278, 280, 283 (descriptions, request and reward texts); gameobjects 257 Suspicious Barrel, 1585 Explosive Charge'),
(3823, 3, 38, 2, 1, 0, 'In Defense of the King''s Lands', 'With the Ironforge Reserve called away to the front, the southern guard tower of Loch Modan must fight a trogg war with a fraction of the soldiers it needs. Captain Rugelfuss cannot spare his regiment from the gate, so he turns to volunteers and asks for trogg teeth as proof of their work. Mountaineer Cobbleflint sends them against Stonesplinter troggs and scouts, Gravelgaw after the skullthumpers and seers of the southern hills, and Wallbang against the shamans and bonesnappers. The hope of relief fades when the promised reinforcements fail to arrive, for the fighting at the front has cost the dwarves dearly. So Rugelfuss chooses to strike at the head of the invasion, sending a volunteer who has proven worthy deep into Stonesplinter Valley to slay the chieftain Grawmug and his guards Gnasher and Brawler.', 'quests 224, 237, 263, 217, 267 (descriptions and reward texts); quest_template_addon PrevQuestID chain 224 > 237 > 263 > 217'),
(3824, 3, 38, 3, 1, 0, 'The Missing Blastpowder', 'Prospector Ironband''s dig has slowed to a crawl, and Jern Hornhelm of the Explorers'' League in Thelsamar wants to know why. The answer from the site is troggs, made berserk by the idols the dwarves had unearthed. Ironband''s report asks for more blastpowder, which puzzles everyone, since a load was sent to him weeks ago. The report goes all the way to the hot-tempered Prospector Stormpike in Ironforge, who approves a new shipment and orders it watched every step of the way. By then Huldar has already set out from Thelsamar with the porters Miran and Saean, and on the road around the loch they are ambushed by Dark Irons. Saean, a porter trusted for nearly a year, turns out to be one of their sympathizers. Miran hauls the last barrels to the site under escort, and Ironband finally gets his powder, though who is supplying the Dark Irons remains a question for another day.', 'quests 436, 297, 298, 301, 302, 273, 454, 309 (descriptions, request and reward texts); creature_text 1379 (Miran); npc_text for Huldar 2057'),
(3825, 3, 38, 4, 1, 0, 'The Ogre Menace', 'Thelsamar has waited months for help from Ironforge, and Magistrate Bluntnose is done waiting. The Mo''grosh ogres camped across the loch have raided the town, the dam and the excavation alike, so he hires mercenaries to cut down the ogres, brutes and enforcers. A wanted notice posted in town names the ogre presumed to lead them, Chok''sul, and promises payment for proof of his death. The ogres have taken more than lives. An ore caravan bound for Thelsamar from the Wetlands was ambushed by them, its last surviving guard dying of his wounds days later. That ore was meant for an alloy the smith Bailor Stonehand promised his old student Jordan Stilwell, and it must now be wrested back from the ogres'' camp before the alloy can be made.', 'quests 255, 256 (descriptions and reward texts); quest 1655 description and reward text; page_text 873 (Jordan trained with Bailor, old teacher); gameobjects 256 WANTED (Thelsamar), 92420 Bailor''s Ore (Mo''grosh Stronghold)'),
(3826, 3, 38, 5, 1, 0, 'Daryl the Bold', 'At the Farstrider Lodge, young Daryl, who styles himself Daryl the Bold, delights in testing newcomers. First he dares them to bring down buzzards against the clock, then elder mountain boars, sneering all the while and promising prizes he never expects to hand over. Those who succeed catch the eye of Vyrin Swiftwind, the lodge''s high elf, who has long wanted someone to humble him. She tells the real story of Daryl''s scar: the lodge''s hunters had failed to kill a great bear called Ol'' Sooty, Daryl tried his own luck, and the bear marked him for it. Vyrin sends the hunter to Ol'' Sooty''s lair in the hills above Thelsamar. When the bear''s head is laid before Daryl his bluster gives way to horror, and Vyrin takes the trophy away, thanking the hunter for a well-earned laugh.', 'quests 257, 258, 271, 531 (descriptions, request and reward texts); npc_text for Vyrin 1156 (thanks for the laugh); quest_template_addon chain 257 > 258 > 271 > 531');
